131	/** The one clean-cut contract this control plane and simulator speak. */
132	const CONTRACT_VERSION = 3;
133	
134	type Body = Record<string, unknown>;
135	
136	/**
137	 * The current carrier route, or no platform block when this deployment has no
138	 * phone route. Model, speech, voice, VAD and media facts cannot enter here.
139	 */
140	function platformBlock(
141	  held: PlatformSettingValues,
142	): Record<string, unknown> | undefined {
143	  // Model and speech fields cannot enter this document from the platform
144	  // store. The persona version owns those choices and the credential source
145	  // below authorizes them. The platform owns only the shared phone route.
146	  const carrier = onlyWhatIsHeld({
147	    trunk_address: held.carrier_trunk_address,
148	    trunk_number: held.carrier_trunk_number,
149	    trunk_username: held.carrier_trunk_username,
150	    trunk_password: held.carrier_trunk_password,
151	  });
152	
153	  const platform = onlyWhatIsHeld({ carrier });
154	  // No carrier means no platform block, not a carrier made of empty fields.
155	  return platform === undefined ? undefined : platform;
156	}
157	
158	/**
159	 * The pinned persona selections with only the credentials this simulation
160	 * can use.
161	 *
162	 * The source is loaded exactly once in this function. A voice simulation gets
163	 * keys for all three legs; a chat simulation gets only its LLM key. The whole
164	 * current bundle never crosses the claim door.
165	 */
166	async function modelsBlock(
167	  modality: SimulationClaim["modality"],
168	  models: PersonaModels,
169	  source: ProviderCredentialSource,
170	): Promise<Record<string, unknown>> {
171	  const credentials = await source.load();
172	  const keyFor = (
173	    provider: PersonaModels["llm"]["provider"],
174	  ): string => credentialFor(credentials, provider);
175	  const speechKey = (
176	    provider: PersonaModels["llm"]["provider"],
177	  ): Record<string, string> =>
178	    modality === "voice" ? { key: keyFor(provider) } : {};
179	
180	  return {
181	    llm: {
182	      provider: models.llm.provider,
183	      model: models.llm.model,
184	      key: keyFor(models.llm.provider),
185	    },
186	    stt: {
187	      provider: models.stt.provider,
188	      model: models.stt.model,
189	      ...speechKey(models.stt.provider),
190	    },
191	    tts: {
192	      provider: models.tts.provider,
193	      model: models.tts.model,
194	      voice_id: models.tts.voiceId,
195	      speed: models.tts.speed,
196	      ...speechKey(models.tts.provider),
197	    },
198	  };
199	}
200	
201	/** One block with its absent fields dropped, or nothing where none is held. */
202	function onlyWhatIsHeld<T>(
203	  fields: Record<string, T | undefined>,
204	): Record<string, T> | undefined {
205	  const present = Object.entries(fields).filter(
206	    ([, value]) => value !== undefined,
207	  );
208	  return present.length === 0
209	    ? undefined
210	    : (Object.fromEntries(present) as Record<string, T>);
211	}
212	
213	/** What a claim request said, once every field has been read and refused for itself. */
214	type ClaimAsk = {
215	  readonly claimant: string;
216	  readonly capacity: number;
217	  /** Seconds this request may be held; already bounded by the cap. */
218	  readonly holdSeconds: number;
219	};
220	
221	/**
222	 * The body as this door reads it, or the sentence refusing it. Each field
223	 * refuses for itself in words that say what to send instead, because the
224	 * reader is the simulator's log and whoever is tailing it.
225	 */
226	function claimAsk(body: Body): ClaimAsk | { readonly refusal: string } {
227	  const claimant = body.claimant;
228	  if (typeof claimant !== "string" || claimant.trim() === "") {
229	    return {
230	      refusal:
231	        "a claim names its claimant — this simulator's own name for itself, " +
232	        'stamped on every row it takes. Send claimant as non-empty text, like ' +
233	        '"egma-simulator-1".',
234	    };
235	  }
236	  if (claimant.trim().length > 200) {
237	    return {
238	      refusal:
239	        "a claimant's name fits in 200 characters; it is a label for telling " +
240	        "two simulators apart, not a place for anything longer.",
241	    };
242	  }
243	
244	  const capacity = body.capacity;
245	  if (typeof capacity !== "number" || !Number.isInteger(capacity) || capacity < 1) {
246	    return {
247	      refusal:
248	        "a claim declares capacity — how many simulations this simulator has " +
249	        "room to conduct at once — as a whole number of at least 1.",
250	    };
251	  }
252	
253	  const wait = body.wait_seconds;
254	  if (
255	    wait !== undefined &&
256	    (typeof wait !== "number" || !Number.isFinite(wait) || wait < 0)
257	  ) {
258	    return {
259	      refusal:
260	        "wait_seconds is how long this request may be held open while the " +
261	        "queue is empty, as a number of seconds of at least 0. Leave it out " +
262	        `and Egma holds for ${DEFAULT_HOLD_SECONDS}.`,
263	    };
264	  }
265	
266	  const contractVersions = body.contract_versions;
267	  if (
268	    !Array.isArray(contractVersions) ||
269	    contractVersions.length === 0 ||
270	    !contractVersions.every(
271	      (version) => typeof version === "number" && Number.isInteger(version),
272	    )
273	  ) {
274	    return {
275	      refusal:
276	        "contract_versions is the simulation-contract versions this worker " +
277	        `implements. Send a non-empty list that includes ${CONTRACT_VERSION}.`,
278	    };
279	  }
280	  if (!contractVersions.includes(CONTRACT_VERSION)) {
281	    return {
282	      refusal:
283	        `this control plane sends simulation contract version ${CONTRACT_VERSION}, ` +
284	        "and this worker does not say it can read it. Deploy the matching " +
285	        "simulator before it claims work.",
286	    };
287	  }
288	
289	  return {
290	    claimant: claimant.trim(),
291	    capacity: Math.min(capacity, LARGEST_CLAIM_CAPACITY),
292	    holdSeconds: Math.min(
293	      wait === undefined ? DEFAULT_HOLD_SECONDS : wait,
294	      LONGEST_HOLD_SECONDS,
295	    ),
296	  };
297	}
298	
299	/**
300	 * One claimed simulation as the wire carries it — the flattened work order
301	 * the contract's spec schema describes — or the reason it could not become
302	 * one.
303	 *
304	 * Everything is read through the claim's own narrowed context, so the
305	 * assembly of one customer's spec happens inside that customer exactly as a
306	 * person's read would. The reads can each come back empty — a connection
307	 * deleted mid-flight, a row from before tests were pinned — and the schema
308	 * check at the end holds whatever was assembled to the same standard the
309	 * simulator's own check will apply on receipt.
310	 */
311	async function assembledSpec(
312	  claim: SimulationClaim,
313	  /**
314	   * The runs already read while answering this one claim request, by id.
315	   *
316	   * A claim takes up to fifty conversations at once and they are usually a
317	   * run's — that is what a run *is* — so the run header would otherwise be
318	   * read fifty times for fifty specs that all want the same frozen world. The
319	   * cache lives for one request and no longer: the header is frozen from the
320	   * moment the run was created, so re-reading it inside one response could
321	   * only ever return the same rows, and a cache that outlived the request
322	   * would be a second copy of a record somebody may since have deleted.
323	   *
324	   * Keyed by run id alone, which is safe because every claim in one batch was
325	   * read through its own row's tenancy and a run id is unique across the
326	   * deployment — two claims naming one run are two conversations of it.
327	   */
328	  runs: Map<string, Run | undefined>,
329	  retellTargets: Map<string, Promise<RetellDirectTargetCheck>>,
330	  providerCredentials: ProviderCredentialSource,
331	  retellFetch?: typeof fetch,
332	  responseDeadline = Date.now() + CLAIM_RESPONSE_MILLISECONDS,
333	): Promise<
334	  | Record<string, unknown>
335	  | { readonly unbuildable: string }
336	  | { readonly retryable: string }
337	> {
338	  const personaVersion = await getPersonaVersion(
339	    claim.auth,
340	    claim.personaVersionId,
341	  );
342	  if (personaVersion === undefined) {
343	    return { unbuildable: "its pinned persona version could not be read" };
344	  }
345	
346	  const evidence = await getSimulationExecutionEvidence(claim.auth, claim.id);
347	  if (evidence === undefined) {
348	    return { unbuildable: "its pinned test version could not be read" };
349	  }
350	  const testVersion = evidence.testVersion;
351	
352	  const connection = await resolveSimulationConnection(claim.auth, claim.id);
353	  if (connection === undefined) {
354	    return {
355	      unbuildable: "its connection is gone or its credentials would not unseal",
356	    };
357	  }
358	
359	  if (connection.connectionType === "retell_chat_api") {
360	    const apiKey = connection.credentials?.["apiKey"] ?? "";
361	    const agentId = connection.config["retellAgentId"] ?? "";
362	    let checked = retellTargets.get(connection.connectionId);
363	    if (checked === undefined) {
364	      checked = verifyRetellChatAgent(
365	        apiKey,
366	        agentId,
367	        retellFetch,
368	        Math.max(1, responseDeadline - Date.now() - 500),
369	      );
370	      retellTargets.set(connection.connectionId, checked);
371	    }
372	    const target = await checked;
373	    if (target.kind === "blocked") {
374	      return { unbuildable: target.message };
375	    }
376	    if (target.kind === "retryable") {
377	      return { retryable: target.message };
378	    }
379	  }
380	
381	  // Read the live carrier route only for `phone_number`. A Retell chat or
382	  // LiveKit room claim must not carry a SIP password it cannot use.
383	  const platform =
384	    connectionTypeUsesPlatformCarrier(connection.connectionType)
385	      ? platformBlock(await resolvePlatformSettings(claim.auth))
386	      : undefined;
387	
388	  if (!runs.has(claim.runId)) {
389	    runs.set(claim.runId, await getRun(claim.auth, claim.runId));
390	  }
391	  const run = runs.get(claim.runId);
392	  if (run === undefined) {
393	    return { unbuildable: "its run could not be read" };
394	  }
395	
396	  // Resolved here and nowhere else. `resolveMockTools` is the one place a
397	  // project default and a test override are folded together, and the
398	  // snapshot it folds was frozen when the run was created — so every
399	  // simulation in one run is served one world, and a mock tool edited
400	  // mid-run tears nothing. The simulator receives the answers already
401	  // decided, exactly as it receives everything else: flattened, with
402	  // nothing left to look up and nothing left to choose between.
403	  const mockTools = resolveMockTools(
404	    evidence.mockToolSnapshot,
405	    claim.testVersionId,
406	  ).map((mock) => ({
407	    tool_name: mock.toolName,
408	    answer: mock.answer,
409	    delay_milliseconds: mock.delayMilliseconds,
410	  }));
411	
412	  let models: Record<string, unknown>;
413	  try {
414	    // The source loads here, once per simulation work order. Persona choices
415	    // are pinned; credentials are current. A rotated AWS bundle therefore
416	    // reaches the next claimed simulation without changing the persona or
417	    // restarting either service.
418	    models = await modelsBlock(
419	      claim.modality,
420	      personaVersion.models,
421	      providerCredentials,
422	    );
423	  } catch (fault) {
424	    if (fault instanceof ProviderCredentialSourceUnavailableError) {
425	      return {
426	        retryable:
427	          "the current model-provider credential bundle could not be read",
428	      };
429	    }
430	    throw fault;
431	  }
432	
433	  const spec = {
434	    contract_version: CONTRACT_VERSION,
435	    simulation_id: claim.id,
436	    modality: claim.modality,
437	    connection: {
438	      agent_platform: connection.agentPlatform,
439	      connection_type: connection.connectionType,
440	      access_variant: connection.accessVariant,
441	      config: connection.config,
442	      credentials: connection.credentials,
443	    },
444	    persona: { traits: personaVersion.traits },
445	    models,
446	    scenario: { instructions: testVersion.scenario },
447	    limits: SIMULATION_LIMITS[claim.modality],
448	    // Left out entirely where the run mocks nothing, which is what most
449	    // runs do: a simulation egma answers no tool for is byte for byte the
450	    // work order it was before mock tools existed, and an empty list
451	    // would be a claim about tools where there is nothing to claim.
452	    ...(mockTools.length === 0 ? {} : { mock_tools: mockTools }),
453	    // No phone route means no platform block.
454	    ...(platform === undefined ? {} : { platform }),
455	  };
456	  // `mockToolId` is deliberately not among the fields sent. The simulator
457	  // records which mock tool answered by its tool name, which is the whole
458	  // of how one is matched; an identifier it would carry and never read is
459	  // a field two sides could come to disagree about.
460	
461	  // Validated on the way out, against the same schema the simulator compiles
462	  // on the way in — so a document that does not speak the contract is this
463	  // side's fault, caught here, rather than a refusal the simulator has to
464	  // explain back over the wire.
465	  const complaints = specComplaints(spec);
466	  if (complaints.length > 0) {
467	    return { unbuildable: `its spec violates the contract: ${complaints.join("; ")}` };
468	  }
469	
470	  return spec;
471	}
