138	 * phone route. Model, speech, voice, VAD and media facts cannot enter here.
139	 */
140	function platformBlock(
141	  held: PlatformSettingValues,
142	): Record<string, unknown> | undefined {
143	  // Model and speech fields cannot enter this document from the platform
144	  // store. The persona version owns those choices and the credential source
145	  // below authorizes them. The platform owns only the shared phone route.
146	  const carrier = onlyWhatIsHeld({
147	    trunk_address: held.carrier_trunk_address,
148	    trunk_number: held.carrier_trunk_number,
149	    trunk_username: held.carrier_trunk_username,
150	    trunk_password: held.carrier_trunk_password,
151	  });
152	
153	  const platform = onlyWhatIsHeld({ carrier });
154	  // No carrier means no platform block, not a carrier made of empty fields.
155	  return platform === undefined ? undefined : platform;
156	}
157	
158	/**
159	 * The pinned persona selections with only the credentials this simulation
160	 * can use.
161	 *
162	 * The source is loaded exactly once in this function. A voice simulation gets
163	 * keys for all three legs; a chat simulation gets only its LLM key. The whole
164	 * current bundle never crosses the claim door.
165	 */
166	async function modelsBlock(
167	  modality: SimulationClaim["modality"],
168	  models: PersonaModels,
169	  source: ProviderCredentialSource,
170	): Promise<Record<string, unknown>> {
171	  const credentials = await source.load();
172	  const keyFor = (
173	    provider: PersonaModels["llm"]["provider"],
174	  ): string => credentialFor(credentials, provider);
175	  const speechKey = (
176	    provider: PersonaModels["llm"]["provider"],
177	  ): Record<string, string> =>
178	    modality === "voice" ? { key: keyFor(provider) } : {};
179	
180	  return {
181	    llm: {
182	      provider: models.llm.provider,
183	      model: models.llm.model,
184	      key: keyFor(models.llm.provider),
185	    },
186	    stt: {
187	      provider: models.stt.provider,
188	      model: models.stt.model,
189	      ...speechKey(models.stt.provider),
190	    },
191	    tts: {
192	      provider: models.tts.provider,
193	      model: models.tts.model,
194	      voice_id: models.tts.voiceId,
195	      speed: models.tts.speed,
196	      ...speechKey(models.tts.provider),
197	    },
198	  };
199	}
