213	/** What a claim request said, once every field has been read and refused for itself. */
214	type ClaimAsk = {
215	  readonly claimant: string;
216	  readonly capacity: number;
217	  /** Seconds this request may be held; already bounded by the cap. */
218	  readonly holdSeconds: number;
219	};
