317	   * run's — that is what a run *is* — so the run header would otherwise be
318	   * read fifty times for fifty specs that all want the same frozen world. The
319	   * cache lives for one request and no longer: the header is frozen from the
320	   * moment the run was created, so re-reading it inside one response could
321	   * only ever return the same rows, and a cache that outlived the request
322	   * would be a second copy of a record somebody may since have deleted.
323	   *
324	   * Keyed by run id alone, which is safe because every claim in one batch was
325	   * read through its own row's tenancy and a run id is unique across the
326	   * deployment — two claims naming one run are two conversations of it.
327	   */
328	  runs: Map<string, Run | undefined>,
329	  retellTargets: Map<string, Promise<RetellDirectTargetCheck>>,
330	  providerCredentials: ProviderCredentialSource,
331	  retellFetch?: typeof fetch,
332	  responseDeadline = Date.now() + CLAIM_RESPONSE_MILLISECONDS,
333	): Promise<
334	  | Record<string, unknown>
335	  | { readonly unbuildable: string }
336	  | { readonly retryable: string }
337	> {
338	  const personaVersion = await getPersonaVersion(
339	    claim.auth,
340	    claim.personaVersionId,
341	  );
342	  if (personaVersion === undefined) {
343	    return { unbuildable: "its pinned persona version could not be read" };
344	  }
345	
346	  const evidence = await getSimulationExecutionEvidence(claim.auth, claim.id);
347	  if (evidence === undefined) {
348	    return { unbuildable: "its pinned test version could not be read" };
349	  }
350	  const testVersion = evidence.testVersion;
351	
352	  const connection = await resolveSimulationConnection(claim.auth, claim.id);
353	  if (connection === undefined) {
354	    return {
355	      unbuildable: "its connection is gone or its credentials would not unseal",
356	    };
357	  }
358	
359	  if (connection.connectionType === "retell_chat_api") {
360	    const apiKey = connection.credentials?.["apiKey"] ?? "";
361	    const agentId = connection.config["retellAgentId"] ?? "";
362	    let checked = retellTargets.get(connection.connectionId);
363	    if (checked === undefined) {
364	      checked = verifyRetellChatAgent(
365	        apiKey,
366	        agentId,
367	        retellFetch,
368	        Math.max(1, responseDeadline - Date.now() - 500),
369	      );
370	      retellTargets.set(connection.connectionId, checked);
371	    }
372	    const target = await checked;
373	    if (target.kind === "blocked") {
374	      return { unbuildable: target.message };
375	    }
376	    if (target.kind === "retryable") {
377	      return { retryable: target.message };
378	    }
379	  }
380	
381	  // Read the live carrier route only for `phone_number`. A Retell chat or
382	  // LiveKit room claim must not carry a SIP password it cannot use.
383	  const platform =
384	    connectionTypeUsesPlatformCarrier(connection.connectionType)
385	      ? platformBlock(await resolvePlatformSettings(claim.auth))
386	      : undefined;
387	
388	  if (!runs.has(claim.runId)) {
389	    runs.set(claim.runId, await getRun(claim.auth, claim.runId));
390	  }
391	  const run = runs.get(claim.runId);
392	  if (run === undefined) {
393	    return { unbuildable: "its run could not be read" };
394	  }
395	
396	  // Resolved here and nowhere else. `resolveMockTools` is the one place a
397	  // project default and a test override are folded together, and the
398	  // snapshot it folds was frozen when the run was created — so every
399	  // simulation in one run is served one world, and a mock tool edited
400	  // mid-run tears nothing. The simulator receives the answers already
401	  // decided, exactly as it receives everything else: flattened, with
402	  // nothing left to look up and nothing left to choose between.
403	  const mockTools = resolveMockTools(
404	    evidence.mockToolSnapshot,
405	    claim.testVersionId,
406	  ).map((mock) => ({
407	    tool_name: mock.toolName,
408	    answer: mock.answer,
409	    delay_milliseconds: mock.delayMilliseconds,
410	  }));
411	
412	  let models: Record<string, unknown>;
413	  try {
414	    // The source loads here, once per simulation work order. Persona choices
415	    // are pinned; credentials are current. A rotated AWS bundle therefore
416	    // reaches the next claimed simulation without changing the persona or
417	    // restarting either service.
418	    models = await modelsBlock(
419	      claim.modality,
420	      personaVersion.models,
421	      providerCredentials,
422	    );
423	  } catch (fault) {
424	    if (fault instanceof ProviderCredentialSourceUnavailableError) {
425	      return {
426	        retryable:
427	          "the current model-provider credential bundle could not be read",
428	      };
429	    }
430	    throw fault;
431	  }
432	
433	  const spec = {
434	    contract_version: CONTRACT_VERSION,
435	    simulation_id: claim.id,
436	    modality: claim.modality,
437	    connection: {
438	      agent_platform: connection.agentPlatform,
439	      connection_type: connection.connectionType,
440	      access_variant: connection.accessVariant,
441	      config: connection.config,
442	      credentials: connection.credentials,
443	    },
444	    persona: { traits: personaVersion.traits },
445	    models,
446	    scenario: { instructions: testVersion.scenario },
447	    limits: SIMULATION_LIMITS[claim.modality],
448	    // Left out entirely where the run mocks nothing, which is what most
449	    // runs do: a simulation egma answers no tool for is byte for byte the
450	    // work order it was before mock tools existed, and an empty list
451	    // would be a claim about tools where there is nothing to claim.
452	    ...(mockTools.length === 0 ? {} : { mock_tools: mockTools }),
453	    // No phone route means no platform block.
454	    ...(platform === undefined ? {} : { platform }),
455	  };
456	  // `mockToolId` is deliberately not among the fields sent. The simulator
457	  // records which mock tool answered by its tool name, which is the whole
458	  // of how one is matched; an identifier it would carry and never read is
459	  // a field two sides could come to disagree about.
460	
461	  // Validated on the way out, against the same schema the simulator compiles
462	  // on the way in — so a document that does not speak the contract is this
463	  // side's fault, caught here, rather than a refusal the simulator has to
464	  // explain back over the wire.
465	  const complaints = specComplaints(spec);
466	  if (complaints.length > 0) {
467	    return { unbuildable: `its spec violates the contract: ${complaints.join("; ")}` };
468	  }
469	
470	  return spec;
471	}
