  1	import {
  2	  completeSimulation,
  3	  failSimulation,
  4	  markSimulationCanceled,
  5	  resolveSimulationStanding,
  6	  startSimulation,
  7	  type CompletedEndingReason,
  8	  type FailedEndingReason,
  9	  type Simulation,
 10	  type SimulationStanding,
 11	  type SimulationSummaryFacts,
 12	} from "@egma/db";
 13	import { reportComplaints } from "@egma/simulation-contract";
 14	import type { FastifyInstance, FastifyReply } from "fastify";
 15	
 16	import { acceptsServiceToken } from "../auth/service-token.ts";
 17	import {
 18	  conflict,
 19	  invalid,
 20	  notFound,
 21	  notTheService,
 22	  unprocessable,
 23	} from "../http/refusals.ts";
 24	
 25	/**
 26	 * The report door: `POST /v1/simulations/:simulationId/reports`, where the
 27	 * simulator says what happened — the lifecycle landing, and only that. What
 28	 * was said in the conversation arrives at the OTLP ingest as spans and never
 29	 * here, which the contract holds rather than this route: a document carrying
 30	 * a turn does not validate, so there is no second record of one conversation
 31	 * for two readers to disagree about.
 32	 *
 33	 * It sits with the claim door on the claim door's exact terms: the service
 34	 * token is the whole gate and resolves to nothing, and the group is outside
 35	 * the per-organization rate limit because the caller is egma's own service
 36	 * standing behind every organization at once. What is different here is
 37	 * where authority over each row comes from. **The token gates the door, and
 38	 * the row names its conductor**: every write below is made under a context
 39	 * derived from the row's own tenancy, in the name of the row's own
 40	 * `claimed_by` — never in the name of anything the request said — so the one
 41	 * secret a simulator holds decides only whether it may knock, and which
 42	 * conversations it speaks for was decided when each row was claimed.
 43	 *
 44	 * **Idempotency without a ledger.** The client delivers at least once and
 45	 * resends byte-identically, so this door must absorb what it has already
 46	 * heard: a `running` for a row already running answers 200, a terminal event
 47	 * matching the row's terminal state answers 200, and only a document that
 48	 * would *rewrite* the record — a different ending, a different terminal
 49	 * status, a running for a finished conversation — is refused with 409. No
 50	 * table of seen event ids exists, on purpose: the row's own state says
 51	 * everything a duplicate check needs, and a ledger would be a second record
 52	 * to keep honest.
 53	 *
 54	 * The shipped simulator posts one event per document; the contract permits
 55	 * several, and they apply in order. Each application commits by itself, so a
 56	 * refusal partway leaves the earlier, valid transitions standing — exactly
 57	 * what a resend of the same document then absorbs as duplicates.
 58	 */
 59	
 60	export type ReportRoutesOptions = {
 61	  /** The deployment's service token, from configuration. */
 62	  readonly serviceToken: string;
 63	};
 64	
 65	export const REPORTS_PATH = "/v1/simulations/:simulationId/reports";
 66	
 67	/** The path one simulation's reports land on — the client's side of the route. */
 68	export function reportPathFor(simulationId: string): string {
 69	  return `/v1/simulations/${simulationId}/reports`;
 70	}
 71	
 72	/** One status event, after the contract check has vouched for its shape. */
 73	type StatusEvent = {
 74	  readonly status: "running" | "completed" | "failed" | "canceled";
 75	  readonly facts?: {
 76	    readonly ending: string;
 77	    readonly started_at: string;
 78	    readonly ended_at: string;
 79	    readonly turn_count: number;
 80	    readonly audio: {
 81	      readonly recording: string;
 82	    } | null;
 83	    readonly provider_reference: string | null;
 84	    /**
 85	     * The one terminal fact that may be omitted, and the only one whose
 86	     * absence is itself a sentence: the agent was never asked what tools it
 87	     * has, so nothing was learned and nothing is claimed.
 88	     */
 89	    readonly mock_tool_coverage?: {
 90	      readonly discovered: readonly string[];
 91	      readonly covered: readonly string[];
 92	      readonly uncovered: readonly string[];
 93	    };
 94	  };
 95	};
 96	
 97	/** The part of an accepted report this route reads. */
 98	type AcceptedReport = {
 99	  readonly simulation_id: string;
100	  readonly events: readonly StatusEvent[];
101	};
102	
103	/**
104	 * The wire's failed endings, as the row's own vocabulary. The two honest
105	 * absences keep their names; the wire's `error` is the row's
106	 * `simulator_error` — same fact, and the row's word for it predates the
107	 * contract's. Everything else — `orphaned` the sweep's word,
108	 * `dispatch_failed` the claim path's, and the rest of the platform's own
109	 * landings — never validates as a document, so it cannot reach this map.
110	 */
111	const FAILED_ENDING_OF: Record<
112	  string,
113	  Exclude<FailedEndingReason, "orphaned" | "dispatch_failed">
114	> = {
115	  agent_never_joined: "agent_never_joined",
116	  not_answered: "not_answered",
117	  error: "simulator_error",
118	};
119	
120	/**
121	 * The reported moments, trusted exactly when they can be true.
122	 *
123	 * A landing given the conduction's own moments writes them over its server
124	 * stamps, so a retried report cannot stretch the record — but a document
125	 * whose `ended_at` precedes its `started_at` describes an interval that
126	 * never existed on any clock, and writing it verbatim would put an
127	 * impossible duration on the row forever. Refusing the document would be
128	 * worse: the reporter treats a final refusal as final, and punishing
129	 * delivery for a skewed clock would turn a truthful conversation into a
130	 * sweep's false orphan. So an incoherent pair is answered with `undefined`,
131	 * the landing falls back to its own server stamps for both moments, and the
132	 * caller logs the pair it declined to believe.
133	 */
134	function reportedMoments(facts: {
135	  readonly started_at: string;
136	  readonly ended_at: string;
137	}): { readonly startedAt: Date; readonly endedAt: Date } | undefined {
138	  const startedAt = new Date(facts.started_at);
139	  const endedAt = new Date(facts.ended_at);
140	  if (endedAt.getTime() < startedAt.getTime()) return undefined;
141	  return { startedAt, endedAt };
142	}
143	
144	/** The terminal facts, as the landings take them. */
145	function summaryFactsOf(event: StatusEvent): SimulationSummaryFacts {
146	  const facts = event.facts;
147	  if (facts === undefined) return {};
148	  return {
149	    turnCount: facts.turn_count,
150	    ...(facts.provider_reference === null
151	      ? {}
152	      : { providerReference: facts.provider_reference }),
153	    ...(facts.audio === null
154	      ? {}
155	      : { recordingReference: facts.audio.recording }),
156	    // Left off where the document left it off, rather than landed as three
157	    // empty lists: absent is the report saying nobody was ever asked, and
158	    // empty is the asking happening and nothing coming back. Writing one for
159	    // the other would be this door inventing a fact the simulator declined to
160	    // claim.
161	    ...(facts.mock_tool_coverage === undefined
162	      ? {}
163	      : { mockToolCoverage: facts.mock_tool_coverage }),
164	    // Absent when incoherent, so the landing's own stamps stand for both.
165	    ...(reportedMoments(facts) ?? {}),
166	  };
167	}
168	
169	/**
170	 * What the row's terminal state would have to be for this event to be a
171	 * resend of it: the same status, and the same ending reason — which for a
172	 * canceled row is no reason at all, because the cancel intent is its own
173	 * record.
174	 */
175	function matchesTerminalRow(
176	  event: StatusEvent,
177	  standing: SimulationStanding,
178	): boolean {
179	  if (standing.status !== event.status) return false;
180	  if (event.status === "canceled") return true;
181	  const ending = event.facts?.ending ?? "";
182	  const reported =
183	    event.status === "failed"
184	      ? FAILED_ENDING_OF[ending]
185	      : (ending as CompletedEndingReason);
186	  return standing.endingReason === reported;
187	}
188	
189	/** Where the row stands, said plainly for a refusal that has to name it. */
190	function standingSentence(standing: SimulationStanding): string {
191	  return standing.endingReason === null
192	    ? standing.status
193	    : `${standing.status} (${standing.endingReason})`;
194	}
195	
196	/** The one shape every applied event answers with. */
197	function landedOn(
198	  reply: FastifyReply,
199	  simulationId: string,
200	  status: string,
201	): FastifyReply {
202	  return reply.code(200).send({ simulation_id: simulationId, status });
203	}
204	
205	export async function reportRoutes(
206	  app: FastifyInstance,
207	  options: ReportRoutesOptions,
208	): Promise<void> {
209	  // The gate, as a hook on this scope rather than a line in the route, for
210	  // the reason the claim door's is one: a route inside this group cannot run
211	  // unguarded, and an unauthenticated request never has its body read.
212	  app.addHook("onRequest", async (request, reply) => {
213	    if (!acceptsServiceToken(request.headers.authorization, options.serviceToken)) {
214	      return notTheService(reply);
215	    }
216	    return undefined;
217	  });
218	
219	  /**
220	   * One report document about one simulation: `status` events apply as
221	   * lifecycle transitions, in order, and the answer names where the row
222	   * stands after the last of them.
223	   */
224	  app.post(REPORTS_PATH, async (request, reply) => {
225	    const { simulationId } = request.params as { simulationId: string };
226	    const document: unknown = request.body ?? {};
227	
228	    // The contract check first, before a byte of the document is believed —
229	    // the same schema the simulator compiled before sending, so the
230	    // complaints going back are the ones its own check would have raised.
231	    // This is also where the reportable vocabulary is held: an ending that
232	    // is the platform's own word (`orphaned` is the sweep's, and the claim
233	    // path lands its own failures) is not in the schema's enums and refuses
234	    // here as a document, never reasoned about as a state.
235	    const complaints = reportComplaints(document);
236	    if (complaints.length > 0) {
237	      return invalid(
238	        reply,
239	        `this is not a simulation report the contract accepts: ` +
240	          `${complaints.join("; ")}. Fix the document against the report ` +
241	          `schema, contract version 1; resending the same bytes cannot help.`,
242	      );
243	    }
244	
245	    // SAFETY: reportComplaints accepted this value against the closed report
246	    // schema, which requires simulation_id and permits only status events.
247	    const report = document as AcceptedReport;
248	
249	    // A document about another simulation is refused, not rerouted: the URL
250	    // and the document each name the simulation, and when they disagree
251	    // there is no honest way to pick one.
252	    if (report.simulation_id !== simulationId) {
253	      return invalid(
254	        reply,
255	        `this document says it is about ${report.simulation_id}, ` +
256	          `but it was posted to ${simulationId}. Post each report to the ` +
257	          `simulation its own simulation_id names.`,
258	      );
259	    }
260	
261	    const standing = await resolveSimulationStanding(simulationId);
262	    if (standing === undefined) {
263	      return notFound(
264	        reply,
265	        `there is no simulation ${simulationId} on this Egma instance. Reports land ` +
266	          `on the simulation a claimed spec named in its simulation_id; ` +
267	          `nothing about this document can be retried.`,
268	      );
269	    }
270	
271	    let lastKnownStatus: string = standing.status;
272	
273	    // Every event here is a lifecycle transition, because the contract check
274	    // above has already refused anything else: a conversation's turns, tool
275	    // calls and measurements arrive as spans at the OTLP door, and a report
276	    // claiming to carry one does not validate.
277	    for (const event of report.events) {
278	      const applied = await applyStatusEvent(reply, simulationId, event);
279	      if (typeof applied !== "string") return applied;
280	      lastKnownStatus = applied;
281	    }
282	
283	    return landedOn(reply, simulationId, lastKnownStatus);
284	  });
285	}
286	
287	/**
288	 * One status event against the row as it now stands: the transition when the
289	 * row is there to move, a 200-worthy nothing when the row already says what
290	 * the event says, and a refusal when the document and the record disagree
291	 * about history. Answers the row's status afterwards, or the refusal it sent.
292	 *
293	 * The row is re-read per event rather than once per document, because each
294	 * event's application moves it and the next event's duplicate check must see
295	 * where it landed. Each read is one indexed select; a document carries a
296	 * handful of events at most.
297	 */
298	async function applyStatusEvent(
299	  reply: FastifyReply,
300	  simulationId: string,
301	  event: StatusEvent,
302	): Promise<FastifyReply | string> {
303	  const standing = await resolveSimulationStanding(simulationId);
304	  if (standing === undefined) {
305	    // It answered moments ago and is gone: the run was deleted mid-request.
306	    return notFound(
307	      reply,
308	        `simulation ${simulationId} is gone from this Egma instance; there is nothing ` +
309	        `left to report against.`,
310	    );
311	  }
312	
313	  return event.status === "running"
314	    ? applyRunning(reply, standing)
315	    : applyTerminal(reply, standing, event);
316	}
317	
318	/**
319	 * `running` — the conversation is underway. The claimant argument on the
320	 * transition is the row's own `claimed_by`: the token gated the door, and
321	 * the row names its conductor, so there is nothing in the request a caller
322	 * could use to speak for somebody else's conversation.
323	 */
324	async function applyRunning(
325	  reply: FastifyReply,
326	  standing: SimulationStanding,
327	): Promise<FastifyReply | string> {
328	  // The duplicate the at-least-once client is owed: already running is what
329	  // this event says, so it is absorbed rather than refused.
330	  if (standing.status === "running") return "running";
331	
332	  if (standing.status === "claimed" && standing.claimedBy !== null) {
333	    const started = await startSimulation(
334	      standing.auth,
335	      standing.id,
336	      standing.claimedBy,
337	    );
338	    if (started !== undefined) return started.status;
339	    // The guarded update matched nothing, so the row moved between the read
340	    // and the write — a duplicate racing this one, or the sweep. Read again
341	    // and answer as the first read would have, one race later.
342	    const moved = await resolveSimulationStanding(standing.id);
343	    if (moved?.status === "running") return "running";
344	    return refusedByTheRecord(reply, moved ?? standing, "running");
345	  }
346	
347	  return refusedByTheRecord(reply, standing, "running");
348	}
349	
350	/**
351	 * The terminal three — the landing, with the facts mapped in. A resend
352	 * matching the row's terminal state is absorbed; a document that would
353	 * rewrite a terminal row is refused; a `canceled` nobody asked for fails
354	 * the landing's own guard and is refused honestly rather than recorded —
355	 * and a `canceled` whose intent landed between the attempt and the answer
356	 * is retried once rather than refused for being early.
357	 */
358	async function applyTerminal(
359	  reply: FastifyReply,
360	  standing: SimulationStanding,
361	  event: StatusEvent,
362	): Promise<FastifyReply | string> {
363	  // A terminal row answers from what it already says: the matching resend
364	  // is absorbed, anything else is a document trying to rewrite the record.
365	  if (
366	    standing.status === "completed" ||
367	    standing.status === "failed" ||
368	    standing.status === "canceled"
369	  ) {
370	    if (matchesTerminalRow(event, standing)) return standing.status;
371	    return refusedByTheRecord(reply, standing, event.status);
372	  }
373	
374	  const facts = event.facts;
375	  if (facts === undefined || standing.claimedBy === null) {
376	    // No facts cannot happen on a validated document; unclaimed means the
377	    // conversation was never anybody's to land.
378	    return refusedByTheRecord(reply, standing, event.status);
379	  }
380	
381	  // The row knows its modality and refuses audio on a chat — said here in a
382	  // sentence rather than surfacing as the database constraint it would trip.
383	  if (facts.audio !== null && standing.modality === "chat") {
384	    return unprocessable(
385	      reply,
386	      `simulation ${standing.id} is a chat conversation, and a chat has no ` +
387	        `audio to measure. Send audio: null, the way the chat fixtures do.`,
388	    );
389	  }
390	
391	  // Said out loud when the reported pair cannot be believed: the landing
392	  // below will stand on its own stamps, and the record of why is this line.
393	  if (reportedMoments(facts) === undefined) {
394	    reply.log.warn(
395	      {
396	        simulationId: standing.id,
397	        reportedStartedAt: facts.started_at,
398	        reportedEndedAt: facts.ended_at,
399	      },
400	      `simulation ${standing.id} reported ended_at before started_at; ` +
401	        `landing with the server's own stamps for both moments`,
402	    );
403	  }
404	
405	  const landed = await applyLanding(standing, event, facts.ending);
406	  if (landed !== undefined) return landed.status;
407	
408	  // The guarded landing matched nothing. Either a duplicate raced this
409	  // request and the row now says what this document says — absorbed — or
410	  // the record genuinely disagrees, and the freshest reading names how.
411	  const moved = await resolveSimulationStanding(standing.id);
412	  if (moved !== undefined && matchesTerminalRow(event, moved)) {
413	    return moved.status;
414	  }
