 94	 * re-claiming the instant every worker declines — and write durable error
 95	 * grades during the exact cold start the retry exists to survive. The hold is
 96	 * the sweep interval, so the retries fall on the clock the backstop already
 97	 * runs on; the job is claimed throughout it, so no other worker takes it, and
 98	 * it is released to the queue only once the hold is over.
 99	 */
100	type Pacing = {
101	  /** Resolve after the backoff, or at once when the service is stopping. */
102	  hold(): Promise<void>;
103	};
104	
105	export function startService(options: ServiceOptions): Service {
106	  const { config, log } = options;
107	
108	  let running = true;
109	  let woken = false;
110	  let wake: (() => void) | undefined;
111	  let watching: Listening | undefined;
112	  /** Cancels for the holds in flight, so `stop` can end every one at once. */
113	  const activeHolds = new Set<() => void>();
114	
115	  /**
116	   * Something may be claimable. Two things arrive here — a notification and the
117	   * backstop — and neither says what: the claim is a query that sees everything
118	   * outstanding, so a nudge is all either of them has to carry.
119	   */
120	  const nudge = (): void => {
121	    woken = true;
122	    wake?.();
123	  };
124	
125	  /** Sleep until nudged, and no longer than the backstop. */
126	  const waitForWork = async (): Promise<void> => {
127	    if (woken) {
128	      woken = false;
129	      return;
130	    }
131	    await new Promise<void>((resolve) => {
132	      const settle = (): void => {
133	        clearTimeout(timer);
134	        wake = undefined;
135	        woken = false;
136	        resolve();
137	      };
138	      const timer = setTimeout(settle, config.sweepSeconds * 1000);
139	      timer.unref();
140	      wake = settle;
141	    });
142	  };
