144	  // The sweep is a positive whole number of seconds, so this is at least the
145	  // second a test sets it to. A still-arriving claim waits this before it is
146	  // released.
147	  const backoffMilliseconds = config.sweepSeconds * 1000;
148	
149	  /** Sleep for the backoff, or return at once when the service is stopping. */
150	  const holdBeforeRetry = (): Promise<void> =>
151	    new Promise<void>((resolve) => {
152	      if (!running) {
153	        resolve();
154	        return;
155	      }
156	      const done = (): void => {
157	        clearTimeout(timer);
158	        activeHolds.delete(done);
159	        resolve();
160	      };
161	      const timer = setTimeout(done, backoffMilliseconds);
162	      timer.unref();
163	      activeHolds.add(done);
164	    });
165	
166	  const pacing: Pacing = { hold: holdBeforeRetry };
167	
168	  const finished = (async (): Promise<void> => {
169	    watching = await watchGradingWork(nudge);
170	    log.info(
171	      platformEvent("egma.service.started", { capacity: config.capacity }),
172	      "grader service started",
173	    );
