249	): Promise<TraceDetail | undefined> {
250	  const cushion = 1_000_000n;
251	  const from = BigInt(claim.traceStartedAt.getTime()) * 1_000n - cushion;
252	  const to = from + BigInt(MAXIMUM_WINDOW_MILLISECONDS) * 1_000n;
253	  const trace = await readTrace(claim.auth, claim.traceId, {
254	    window: { from, to },
