256	  if (trace === undefined) {
257	    return undefined;
258	  }
259	  if (trace.source !== claim.source) {
260	    throw new NotGradable(
261	      `trace ${claim.traceId} is ${trace.source}, not ${claim.source}`,
262	    );
263	  }
264	  return trace;
265	}
