151	/** Resolve every selected model before any executor starts. */
152	function judgesFor(
153	  entries: readonly FrozenGradingEntry[],
154	  credentials: ProviderCredentialBundle,
155	  makers: JudgeMakers,
156	): ReadonlyMap<string, AskableJudge> {
157	  const judges = new Map<string, AskableJudge>();
158	  for (const entry of entries) {
159	    if (entry.definition.type === "code") continue;
160	    if (entry.definition.judgeModel === null) {
161	      throw new Error(
162	        `model-judged definition ${entry.graderDefinitionId} version ${entry.graderDefinitionVersion} has no judge model`,
163	      );
164	    }
165	    judges.set(
166	      entry.projectGraderId,
167	      judgeFor(entry.definition.judgeModel, credentials, makers),
168	    );
169	  }
170	  return judges;
171	}
