173	function gradeRow(
174	  claim: GradingClaim,
175	  entry: FrozenGradingEntry,
176	  result: GraderResult,
177	): NewGrade {
178	  return {
179	    source: claim.source,
180	    traceId: claim.traceId,
181	    traceStartedAtMicroseconds: BigInt(claim.traceStartedAt.getTime()) * 1_000n,
182	    runId: claim.runId ?? "",
183	    projectGraderId: entry.projectGraderId,
184	    graderDefinitionId: entry.graderDefinitionId,
185	    graderDefinitionVersion: entry.graderDefinitionVersion,
186	    score: result.score,
187	    details: result.details,
188	    graderPassThreshold: entry.graderPassThreshold,
189	    gradingSequence: claim.sequenceBase + claim.attempts,
190	    gradedAtMicroseconds: gradedNow(),
191	  };
192	}
