194	async function resolveConversation(claim: GradingClaim): Promise<Resolved> {
195	  if (claim.source === "production") {
196	    const trace = await traceFor(claim);
197	    if (trace === undefined) {
198	      throw new NotGradable(
199	        `production trace ${claim.traceId} is no longer readable in its frozen window`,
200	      );
201	    }
202	    return { conversation: conversationOfTrace(trace), simulationId: undefined };
203	  }
204	  if (claim.simulationId === null) {
205	    throw new NotGradable(`simulation grading job ${claim.id} names no simulation`);
206	  }
207	  const simulation = await getSimulation(claim.auth, claim.simulationId);
208	  if (simulation === undefined || simulation.status !== "completed") {
209	    throw new NotGradable(
210	      `simulation ${claim.simulationId} is not a completed trace the job can read`,
211	    );
212	  }
213	  if (claim.runId === null || claim.runId !== simulation.runId) {
214	    throw new NotGradable(
215	      `grading job ${claim.id} does not name simulation ${simulation.id}'s run`,
216	    );
217	  }
218	
219	  const trace = await traceFor(claim);
220	  if (trace !== undefined && trace.runId !== claim.runId) {
221	    throw new NotGradable(
222	      `trace ${trace.traceId} does not carry its frozen simulation run`,
223	    );
224	  }
225	
226	  // A simulation can reach its terminal row before accepted evidence becomes
227	  // readable. Ask again while the retry budget remains. On the final attempt,
228	  // write error grades from the missing or partial conversation instead of
229	  // abandoning work that can no longer improve.
230	  if (
231	    evidenceIsStillArriving(simulation, trace) &&
232	    claim.attempts < MOST_GRADING_ATTEMPTS
233	  ) {
234	    throw new NotGradable(
235	      `simulation ${simulation.id} is complete and egma does not hold all of ` +
236	        `its conversation yet, so there is nothing to grade on attempt ` +
237	        `${claim.attempts} of ${MOST_GRADING_ATTEMPTS}`,
238	    );
239	  }
240	
241	  return {
242	    conversation: conversationOfSimulation(simulation, trace),
243	    simulationId: simulation.id,
244	  };
245	}
