247	async function traceFor(
248	  claim: GradingClaim,
249	): Promise<TraceDetail | undefined> {
250	  const cushion = 1_000_000n;
251	  const from = BigInt(claim.traceStartedAt.getTime()) * 1_000n - cushion;
252	  const to = from + BigInt(MAXIMUM_WINDOW_MILLISECONDS) * 1_000n;
253	  const trace = await readTrace(claim.auth, claim.traceId, {
254	    window: { from, to },
255	  });
256	  if (trace === undefined) {
257	    return undefined;
258	  }
259	  if (trace.source !== claim.source) {
260	    throw new NotGradable(
261	      `trace ${claim.traceId} is ${trace.source}, not ${claim.source}`,
262	    );
263	  }
264	  return trace;
265	}
