267	/** Preserve completion order inside one worker; the job sequence orders workers. */
268	let lastStamp = 0n;
269	function gradedNow(): bigint {
270	  const now = BigInt(Date.now()) * 1_000n;
271	  lastStamp = now > lastStamp ? now : lastStamp + 1n;
272	  return lastStamp;
273	}

