 58	 * that the conversation ended and ingestion states that its evidence is
 59	 * query-visible. A root span or silence never creates work here.
 60	 */
 61	export type Service = {
 62	  /** Runs until `stop` is called; resolves when the last job has landed. */
 63	  readonly finished: Promise<void>;
 64	  stop(): void;
 65	};
