550	/** Start one complete suite under one exact database lock. */
551	export async function startRun(auth: AuthContext, input: NewRun): Promise<StartedRun> {
552	  authorize(auth, "start_and_cancel_runs", here(auth));
553	  const { projectId } = auth;
554	  if (projectId === undefined) throw new Error("a run happens inside a project");
555	  if (!isId("ste", input.suiteId)) refuseRun("not_admitted", `"${input.suiteId}" is not a test suite id`);
556	  if (!isId("agt", input.agentId)) refuseRun("connection_not_on_agent", `"${input.agentId}" is not an agent id`);
557	  if (!isId("con", input.connectionId)) refuseRun("no_such_connection", `"${input.connectionId}" is not a connection id`);
558	  const idempotencyKey = input.idempotencyKey.trim();
559	  if (idempotencyKey === "") refuseRun("not_admitted", "a run needs an idempotency key");
560	  const expected = validateExpectedVersions(input.expectedTestVersions);
561	  const expectedInOrder = expected === undefined
562	    ? undefined
563	    : [...expected].sort((a, b) => a.testId.localeCompare(b.testId));
564	  const remembered = await originalRunFor(db(), auth, projectId, input);
565	  if (remembered !== undefined) return remembered;
566	
567	  const runId = newId("run");
568	  const at = new Date();
569	  let created: Run | undefined;
570	  try {
571	    created = await db().transaction(async (tx) => {
572	      const [suite] = await tx
573	        .select({ id: testSuite.id, name: testSuite.name })
574	        .from(testSuite)
575	        .where(within(auth, testSuite, and(
576	          eq(testSuite.id, input.suiteId),
577	          eq(testSuite.projectId, projectId),
578	          isNull(testSuite.deletedAt),
579	        )))
580	        .limit(1)
581	        .for("update");
582	      if (suite === undefined) refuseRun("not_admitted", `there is no active test suite ${input.suiteId} in this project`);
583	
584	      const readTestPage = (afterId?: string) => tx
585	        .select({ id: test.id, versionId: test.currentVersionId })
586	        .from(test)
587	        .where(and(
588	          eq(test.suiteId, suite.id),
589	          eq(test.projectId, projectId),
590	          isNull(test.deletedAt),
591	          afterId === undefined ? undefined : gt(test.id, afterId),
592	        ))
593	        .orderBy(asc(test.id))
594	        .limit(SIMULATION_INSERT_BATCH)
595	        .for("share", { of: test });
596	      let currentTests = await readTestPage();
597	      if (currentTests.length === 0) refuseRun("not_admitted", `test suite ${suite.id} is empty`);
598	
599	      const [reached] = await tx
600	        .select({
601	          agentId: connection.agentId,
602	          // The connection holds no platform of its own: the type answers
603	          // where it pins one, else the agent's own binding does.
604	          agentPlatform: agent.agentPlatform,
605	          connectionType: connection.connectionType,
606	          accessVariant: connection.accessVariant,
607	          modality: connection.modality,
608	          topology: connection.topology,
609	          environment: connection.environment,
610	          config: connection.config,
611	        })
612	        .from(connection)
613	        .innerJoin(agent, eq(connection.agentId, agent.id))
614	        .where(within(auth, connection, and(
615	          eq(connection.id, input.connectionId),
616	          eq(connection.agentId, input.agentId),
617	          eq(connection.projectId, projectId),
618	          isNull(connection.archivedAt),
619	          isNull(agent.archivedAt),
620	        )))
621	        .limit(1)
622	        .for("share");
623	      if (reached === undefined) refuseRun("no_such_connection", `there is no active connection ${input.connectionId} on agent ${input.agentId}`);
624	      if (!connectionIsConductable(reached.connectionType, reached.accessVariant, reached.modality)) {
625	        refuseRun("no_adapter", noSimulatorAdapterMessage(reached.connectionType, reached.modality));
626	      }
627	
628	      const graderCandidates = await applicableGraders(auth, tx, projectId);
629	      const plannedTests: {
630	        suiteId: string;
631	        testId: string;
632	        testVersionId: string;
633	        modality: Modality;
634	      }[] = [];
635	      const mockToolSnapshot = await freezeMockTools(
636	        tx,
637	        auth,
638	        projectId,
639	        reached.agentId,
640	      );
641	      const [measured] = await tx
642	        .select({ total: count() })
643	        .from(test)
644	        .innerJoin(testPersona, eq(test.currentVersionId, testPersona.testVersionId))
645	        .where(and(
646	          eq(test.suiteId, suite.id),
647	          eq(test.projectId, projectId),
648	          isNull(test.deletedAt),
649	        ));
650	      const expectedSimulationCount = measured?.total ?? 0;
651	      if (expectedSimulationCount <= 0) {
652	        refuseRun("not_admitted", `test suite ${suite.id} is empty`);
653	      }
654	
655	      const [header] = await tx.insert(run).values({
656	        id: runId,
657	        organizationId: auth.organizationId,
658	        projectId,
659	        suiteId: suite.id,
660	        agentId: reached.agentId,
661	        connectionId: input.connectionId,
662	        name: input.name?.trim() || null,
663	        status: "pending",
664	        triggeredVia: "manual",
665	        triggeredBy: auth.userId,
666	        connectionSnapshot: {
667	          // Derived exactly as a read derives it: the type answers where it
668	          // pins one platform, else the agent's own binding does.
669	          agentPlatform:
670	            platformOfConnectionType(reached.connectionType) ??
671	            reached.agentPlatform,
672	          connectionType: reached.connectionType,
673	          accessVariant: reached.accessVariant,
674	          modality: reached.modality,
675	          topology: reached.topology,
676	          environment: reached.environment,
677	          config: reached.config,
678	        },
679	        mockToolSnapshot,
680	        expectedSimulationCount,
681	        createdAt: at,
682	      }).returning(RUN_COLUMNS);
683	      if (header === undefined) throw new Error("the run was not written");
684	
685	      let simulationCount = 0;
686	      let expectedIndex = 0;
687	      while (currentTests.length > 0) {
688	        for (const current of currentTests) {
689	          const expectedCurrent = expectedInOrder?.[expectedIndex];
690	          if (
691	            expectedInOrder !== undefined &&
692	            (expectedCurrent?.testId !== current.id || expectedCurrent.versionId !== current.versionId)
693	          ) {
694	            refuseRun("not_admitted", "the suite changed after this run request was prepared; read it again and retry");
695	          }
696	          expectedIndex += 1;
697	          plannedTests.push({
698	            suiteId: suite.id,
699	            testId: current.id,
700	            testVersionId: current.versionId,
701	            modality: reached.modality as Modality,
702	          });
703	
704	          let personaPosition = 0;
705	          let namedPersona = false;
706	          while (true) {
707	            const personaRows = await tx
708	              .select({
709	                personaId: testPersona.personaId,
710	                position: testPersona.position,
711	              })
712	              .from(testPersona)
713	              .where(and(
714	                eq(testPersona.testVersionId, current.versionId),
715	                gt(testPersona.position, personaPosition),
716	              ))
717	              .orderBy(asc(testPersona.position))
718	              .limit(SIMULATION_INSERT_BATCH);
719	            if (personaRows.length === 0) break;
720	            namedPersona = true;
721	            const pins = await resolvePersonaVersions(
722	              auth,
723	              tx,
724	              projectId,
725	              personaRows.map((one) => one.personaId),
726	            );
727	            await tx.insert(simulation).values(pins.map((pin, index) => ({
728	              id: newId("sim"),
729	              runId,
730	              organizationId: auth.organizationId,
731	              projectId,
732	              agentId: reached.agentId,
733	              connectionId: input.connectionId,
734	              personaId: pin.personaId,
735	              personaVersionId: pin.personaVersionId,
736	              testId: current.id,
737	              testVersionId: current.versionId,
738	              position: simulationCount + index + 1,
739	              modality: reached.modality,
740	              status: "queued" as const,
741	              createdAt: at,
742	            })));
743	            simulationCount += pins.length;
744	            personaPosition = personaRows.at(-1)?.position ?? personaPosition;
745	            if (personaRows.length < SIMULATION_INSERT_BATCH) break;
746	          }
747	          if (!namedPersona) throw new Error(`test version ${current.versionId} names no persona`);
748	        }
749	        if (currentTests.length < SIMULATION_INSERT_BATCH) break;
750	        const afterTestId = currentTests.at(-1)?.id;
751	        if (afterTestId === undefined) break;
752	        currentTests = await readTestPage(afterTestId);
753	      }
754	      if (expectedInOrder !== undefined && expectedIndex !== expectedInOrder.length) {
755	        refuseRun("not_admitted", "the suite changed after this run request was prepared; read it again and retry");
756	      }
757	      if (simulationCount !== expectedSimulationCount) {
758	        throw new Error(`test suite ${suite.id} changed while its run was being planned`);
759	      }
760	      const groups = planGroupsFor(graderCandidates, plannedTests);
  1	import { newId } from "@egma/ids";
